CREATE TABLE IF NOT EXISTS pve_regions (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', sort_order INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pve_nodes (id INTEGER PRIMARY KEY AUTOINCREMENT, region_id INTEGER NOT NULL, name TEXT NOT NULL, host TEXT NOT NULL, port INTEGER NOT NULL DEFAULT 8006, cluster_name TEXT NOT NULL DEFAULT '', api_user TEXT NOT NULL, api_token_id TEXT NOT NULL, api_token_secret TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', last_checked_at INTEGER, last_error TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY(region_id) REFERENCES pve_regions(id));
CREATE TABLE IF NOT EXISTS pve_instance_flavors (instance_flavor_id INTEGER PRIMARY KEY AUTOINCREMENT, instance_flavor_code TEXT NOT NULL, name TEXT NOT NULL, cpu_cores INTEGER NOT NULL, memory_gb INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', sort_order INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(cpu_cores, memory_gb));
CREATE TABLE IF NOT EXISTS pve_vms (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL DEFAULT 'qemu', region_id INTEGER NOT NULL, node_id INTEGER NOT NULL, instance_flavor_id INTEGER NOT NULL, name TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'allocating', pve_status TEXT NOT NULL DEFAULT '', pve_config TEXT NOT NULL DEFAULT '{}', error_message TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, FOREIGN KEY(region_id) REFERENCES pve_regions(id), FOREIGN KEY(node_id) REFERENCES pve_nodes(id), FOREIGN KEY(instance_flavor_id) REFERENCES pve_instance_flavors(instance_flavor_id));
CREATE TABLE IF NOT EXISTS pve_vm_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, vm_id INTEGER NOT NULL, action TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', request_payload TEXT NOT NULL DEFAULT '{}', response_payload TEXT NOT NULL DEFAULT '{}', retry_count INTEGER NOT NULL DEFAULT 0, error_message TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY(vm_id) REFERENCES pve_vms(id));
